-- ══════════════════════════════════════════════════════════════════════
-- Generalizar la plantilla del Acuerdo Pedagógico (migración NUEVA, no un
-- retoque de la anterior).
--
-- ── Por qué hace falta esta migración ─────────────────────────────────
-- La 20261760000000 sembró la plantilla y YA SE APLICÓ. Después se editó ese
-- mismo archivo para generalizarla, y el pipeline la SALTÓ: las migraciones se
-- aplican una vez y no se vuelven a correr ("Saltadas (ya estaban): 547"). O
-- sea que la generalización quedó en el repositorio y nunca llegó a la base: en
-- producción la plantilla seguía con los objetivos y los cortes de Programación
-- II escritos a mano. Este archivo la ACTUALIZA de verdad.
--
-- Regla que esto deja escrita: para cambiar el contenido de algo ya sembrado,
-- una migración nueva. Editar la vieja no hace nada, y encima no se nota.
--
-- ── Qué queda general y qué no ────────────────────────────────────────
-- Todo lo que dependa del curso sale de los datos:
--   {{curso.programa}} {{curso.nombre}} {{curso.grupo}} {{curso.semestre}}
--   {{periodo}} {{docente.nombre}} {{fecha_emision}} {{curso.objetivos}}
--   {{total_estudiantes}} y la tabla de evaluación con {{#each cortes_curso}}
--
-- Lo único que NO es general es la LISTA DE FIRMAS: ahí van los estudiantes
-- concretos del curso, uno por fila, con su nombre y código y la celda de firma
-- en blanco. Es el punto del documento — una lista de firmas genérica no serviría
-- para nada.
--
-- Lo que queda como texto fijo es solo lo que pertenece al FORMATO y no a un
-- curso: los rótulos de las tablas, la frase de aprobación del acuerdo, las
-- etiquetas "El Docente / Tutor · El Vocero · Director", el anexo, y una
-- indicación de qué escribir en la sección metodológica (que es prosa que
-- redacta el docente y no hay dato del que sacarla).
-- ══════════════════════════════════════════════════════════════════════

DO $mig$
DECLARE
  v_n int := 0;
BEGIN
  IF to_regclass('public.report_templates') IS NULL THEN
    RAISE NOTICE 'report_templates ausente — se omite la actualización del acuerdo';
    RETURN;
  END IF;

  UPDATE public.report_templates SET
    description = 'Formato DO-F-021. Toma del curso el programa, grupo, semestre, periodo, docente y objetivos de la asignatura; la tabla de evaluación sale de los cortes; el listado de firmas, de la matrícula.',
    scope       = 'curso',
    body_html   = $tpl$<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Programa Académico</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.programa}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Nombre Del Curso</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.nombre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Grupo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.grupo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Semestre</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.semestre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Periodo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{periodo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Fecha</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{fecha_emision}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Profesor</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{docente.nombre}}</span></p></td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:middle;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt;color:#000000;font-family:'Arial'">Objetivos del Curso</span></p><td style="padding:4px 6px;vertical-align:top;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt;white-space:pre-line">{{curso.objetivos}}</span></p></td></tr><tr><td colspan="4" style="padding:4px 6px;vertical-align:top;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Una vez presentada la agenda de trabajo, las estrategias metodológicas y criterios de evaluación estos se aprueban, se modifican o se complementan</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;">&nbsp;</td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos metodológicos</span></p><p style="text-align:justify"><span style="font-size:9pt">Describa acá la modalidad de las clases, la metodología acordada y la dinámica de cada sesión.</p></td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos de evaluación</span></p><p style="text-align:justify"><span style="font-size:9pt">La nota final se compone de los siguientes cortes:</span></p><table style="border-collapse:collapse;width:100%;margin-top:6px;table-layout:fixed;"><tr><td style="padding:3px 5px;border:1px solid #444;width:26%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Corte</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:12%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Peso</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:32%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Fechas</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:30%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Distribución</strong></span></td></tr>{{#each cortes_curso}}<tr><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{nombre}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{peso}}%</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{inicio}} a {{fin}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">Exámenes {{peso_examenes}}% · Talleres {{peso_talleres}}% · Proyectos {{peso_proyectos}}% · Asistencia {{peso_asistencia}}%</span></td></tr>{{/each}}</table><tr><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:18%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Total de Estudiantes asistentes al acuerdo</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:31.9%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{total_estudiantes}}</span></p></td></tr><tr><td colspan="2" style="padding:4px 6px;vertical-align:middle;width:8.9%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Nombre del vocero</span></p></td><td colspan="4" style="padding:4px 6px;vertical-align:middle;width:41%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:4.7%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Teléfono</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:21%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:4.2%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">E–mail</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:20%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:10pt">&nbsp;</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:4.7%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Ciudad</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:21%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:4.2%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Fecha</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:20%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{fecha_emision}}</span></p></td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>El Docente / Tutor</strong></span></p></td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>El Vocero</strong></span></p></td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Director</strong></span></p></td></tr></table>
<p><span style="font-size:9pt">Anexo: Agendas de trabajo y lista de estudiantes asistentes.</span></p>
<p style="text-align:center"><strong>LISTADO DE ESTUDIANTES ASISTENTES AL ACUERDO </strong></p>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;border:1px solid #444;width:7%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>N°.</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:41%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Estudiante</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:22%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Código</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:30%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Firma</strong></span></p></td></tr>{{#each estudiantes}}<tr><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{@number}}</span></td><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{nombre}}</span></td><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{codigo}}</span></td><td style="padding:4px 6px;border:1px solid #444;height:30px;">&nbsp;</td></tr>{{/each}}</table>$tpl$,
    header_html = $tplh$<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="width:26.8%;padding:2px 6px;vertical-align:middle;"><img src="{{institucion.logo}}" style="width:173px;max-width:100%;height:auto;" alt="" /></td><td style="width:47.4%;padding:2px 6px;vertical-align:middle;"><p style="text-align:center"><span style="font-size:14pt;color:#000000;font-family:'Arial'"><strong>ACUERDO PEDAGÓGICO </strong></span></p></td><td style="width:25.7%;padding:2px 6px;vertical-align:middle;"><p style="text-align:right"><span style="font-size:8pt;color:#000000;font-family:'Arial'">V – 1.0 – 2019</span></p><p style="text-align:right"><span style="font-size:8pt;color:#000000;font-family:'Arial'">DO-F-021</span></p></td></tr></table>$tplh$,
    updated_at  = now()
   WHERE name = 'Acuerdo Pedagógico'
     AND owner_id IS NULL AND course_id IS NULL AND parent_id IS NULL;

  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- Si no existía (entorno donde la 20261760000000 no corrió), se crea.
  IF v_n = 0 THEN
    INSERT INTO public.report_templates
      (name, description, scope, body_html, header_html, page_size, page_orientation,
       owner_id, course_id, parent_id)
    VALUES (
      'Acuerdo Pedagógico',
      'Formato DO-F-021 con los datos del curso, el bloque de firmas y el listado de estudiantes generado desde la matrícula.',
      'curso',
      $tpl2$<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Programa Académico</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.programa}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Nombre Del Curso</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.nombre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Grupo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.grupo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Semestre</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.semestre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Periodo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{periodo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Fecha</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{fecha_emision}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Profesor</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{docente.nombre}}</span></p></td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:middle;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt;color:#000000;font-family:'Arial'">Objetivos del Curso</span></p><td style="padding:4px 6px;vertical-align:top;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt;white-space:pre-line">{{curso.objetivos}}</span></p></td></tr><tr><td colspan="4" style="padding:4px 6px;vertical-align:top;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Una vez presentada la agenda de trabajo, las estrategias metodológicas y criterios de evaluación estos se aprueban, se modifican o se complementan</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;">&nbsp;</td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos metodológicos</span></p><p style="text-align:justify"><span style="font-size:9pt">Describa acá la modalidad de las clases, la metodología acordada y la dinámica de cada sesión.</p></td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos de evaluación</span></p><p style="text-align:justify"><span style="font-size:9pt">La nota final se compone de los siguientes cortes:</span></p><table style="border-collapse:collapse;width:100%;margin-top:6px;table-layout:fixed;"><tr><td style="padding:3px 5px;border:1px solid #444;width:26%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Corte</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:12%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Peso</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:32%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Fechas</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:30%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Distribución</strong></span></td></tr>{{#each cortes_curso}}<tr><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{nombre}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{peso}}%</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{inicio}} a {{fin}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">Exámenes {{peso_examenes}}% · Talleres {{peso_talleres}}% · Proyectos {{peso_proyectos}}% · Asistencia {{peso_asistencia}}%</span></td></tr>{{/each}}</table><tr><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:18%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Total de Estudiantes asistentes al acuerdo</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:31.9%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{total_estudiantes}}</span></p></td></tr><tr><td colspan="2" style="padding:4px 6px;vertical-align:middle;width:8.9%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Nombre del vocero</span></p></td><td colspan="4" style="padding:4px 6px;vertical-align:middle;width:41%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:4.7%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Teléfono</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:21%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:4.2%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">E–mail</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:20%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:10pt">&nbsp;</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:4.7%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Ciudad</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:21%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">&nbsp;</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:4.2%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Fecha</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:20%;border:1px solid #444;"><p style="text-align:center"><span style="font-size:9pt">{{fecha_emision}}</span></p></td></tr></table>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;">&nbsp;</td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>El Docente / Tutor</strong></span></p></td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>El Vocero</strong></span></p></td><td style="padding:4px 6px;vertical-align:top;width:16.7%;border:1px solid #444;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Director</strong></span></p></td></tr></table>
<p><span style="font-size:9pt">Anexo: Agendas de trabajo y lista de estudiantes asistentes.</span></p>
<p style="text-align:center"><strong>LISTADO DE ESTUDIANTES ASISTENTES AL ACUERDO </strong></p>
<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;border:1px solid #444;width:7%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>N°.</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:41%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Estudiante</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:22%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Código</strong></span></p></td><td style="padding:4px 6px;border:1px solid #444;width:30%;background-color:#d9d9d9;"><p style="text-align:center"><span style="font-size:9pt"><strong>Firma</strong></span></p></td></tr>{{#each estudiantes}}<tr><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{@number}}</span></td><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{nombre}}</span></td><td style="padding:4px 6px;border:1px solid #444;"><span style="font-size:9pt">{{codigo}}</span></td><td style="padding:4px 6px;border:1px solid #444;height:30px;">&nbsp;</td></tr>{{/each}}</table>$tpl2$,
      $tplh2$<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="width:26.8%;padding:2px 6px;vertical-align:middle;"><img src="{{institucion.logo}}" style="width:173px;max-width:100%;height:auto;" alt="" /></td><td style="width:47.4%;padding:2px 6px;vertical-align:middle;"><p style="text-align:center"><span style="font-size:14pt;color:#000000;font-family:'Arial'"><strong>ACUERDO PEDAGÓGICO </strong></span></p></td><td style="width:25.7%;padding:2px 6px;vertical-align:middle;"><p style="text-align:right"><span style="font-size:8pt;color:#000000;font-family:'Arial'">V – 1.0 – 2019</span></p><p style="text-align:right"><span style="font-size:8pt;color:#000000;font-family:'Arial'">DO-F-021</span></p></td></tr></table>$tplh2$,
      'A4', 'portrait', NULL, NULL, NULL
    );
    RAISE NOTICE 'Acuerdo Pedagógico creado (no existía)';
  ELSE
    RAISE NOTICE 'Acuerdo Pedagógico actualizado (% fila)', v_n;
  END IF;
END $mig$;
